import React, { useState } from 'react';
import './StartQuiz.css';

function StartQuiz() {

  const quizzes = [
    { id: "podst-1", title: "Podstawy – Quiz 1", level: "podstawowy", questions: 20 },
    { id: "podst-2", title: "Podstawy – Quiz 2", level: "podstawowy", questions: 25 },
    { id: "rozs-1", title: "Rozszerzenie – Quiz 1", level: "rozszerzony", questions: 30 },
    { id: "rozs-2", title: "Rozszerzenie – Quiz 1", level: "rozszerzony", questions: 30 },
  ];
  const [quizzesList, setQuizzesList] = useState(quizzes);

  return (
    <div className='maturazinformatyki-quiz'>
      <header className='maturazinformatyki-quiz-app-header'>
        <div className='maturazinformatyki-quiz-container'>
          <h1>Wybierz quiz</h1>
          <p className='maturazinformatyki-quiz-subtitle'>
            Zacznij od wyboru tematu (poziomu), a potem rozpocznij test.
          </p>
        </div>
      </header>
      <main className='maturazinformatyki-quiz-container'>
      <section id="view-picker" className="maturazinformatyki-quiz-card-list">
        <div className="maturazinformatyki-quiz-card-header">
          <h2>Dostępne quizy</h2>
        </div>
        {quizzesList.length > 0 ? (
          <div 
            id="maturazinformatyki-quiz-quizList" 
            className="maturazinformatyki-quiz-grid" 
          >
            {/* list quiz */}
            {quizzesList.map( quiz=>(
              <div className='maturazinformatyki-quiz-grid-quiz'>
                e
              </div>   
            ))}

          </div>
        ) : (
        <p id="emptyState" className="muted hidden">
          Brak wyników dla podanych filtrów.
        </p>
        ) }
        <p>
            {quizzesList.map((quiz) => (
                <article key={quiz.id} className="quiz-tile">
                  <h3 className="quiz-title">{quiz.title}</h3>
                  <p className="muted">
                    Poziom: {quiz.level} • Pytań: {quiz.questions}
                  </p>

                  {/* Przykładowy przycisk startu */}
                  <button
                    type="button"
                    className="primary"
                    onClick={() => {
                      // tutaj np. navigate(`/quiz/${quiz.id}`) jeśli używasz react-router
                      console.log("Start quiz:", quiz.id);
                    }}
                  >
                    Rozpocznij
                  </button>
                </article>
                        ))}
        </p>
      </section>

      </main>
    </div>
  )
}

export default StartQuiz
